import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"十四寒","description":"","frontmatter":{"title":"十四寒","date":"2026-11-17T00:00:00.000Z","seq":14,"categories":["美文","声律启蒙"],"collection":"《声律启蒙 · 上卷》","tags":["声律启蒙","清"],"poem":true,"poem_quote":false,"author":"佚名","source_book":"声律启蒙"},"headers":[],"relativePath":"blogs/声律启蒙·上卷/十四寒.md","filePath":"blogs/声律启蒙·上卷/十四寒.md"}'),r={name:"blogs/声律启蒙·上卷/十四寒.md"};function p(_,e,l,c,n,i){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="十四寒" tabindex="-1">十四寒 <a class="header-anchor" href="#十四寒" aria-label="Permalink to &quot;十四寒&quot;">​</a></h1><p class="poem-meta">清 · 佚名　·　上卷</p><div class="poem"><p class="poem-stanza">多对少，易对难，虎踞对龙蟠。龙舟对凤辇，白鹤对青鸾。风淅淅，露漙漙，绣毂对雕鞍。鱼游荷叶沼，鹭立蓼花滩。有酒阮貂奚用解，无鱼冯铗必须弹。丁固梦松，柯叶忽然生腹上；文郎画竹，枝梢倏尔长毫端。</p><p class="poem-stanza">寒对暑，湿对干，鲁隐对齐桓。寒毡对暖席，夜饮对晨餐。叔子带，仲由冠，郏鄏对邯郸。嘉禾忧夏旱，衰柳耐秋寒。杨柳绿遮元亮宅，杏花红映仲尼坛。江水流长，环绕似青罗带；海蟾轮满，澄明如白玉盘。</p><p class="poem-stanza">横对竖，窄对宽，黑志对弹丸。朱帘对画栋，彩槛对雕栏。春既老，夜将阑，百辟对千官。怀仁称足足，抱义美般般。好马君王曾市骨，食猪处士仅思肝。世仰双仙，元礼舟中携郭泰，人称连壁，夏侯车上并潘安。</p></div>',3)])])}const u=a(r,[["render",p]]);export{d as __pageData,u as default};
